"""Build a self-contained, fetch-free review viewer for the six collection delivery.
Only ROOT/preview.html is written. Metadata can fall back to the build workspace;
all emitted artifact URLs keep the final reviews/NAME/... staging structure.
Use --serve for a read-only draft server that resolves those URLs to workspace
artifacts when staging has not yet been populated.
"""
from pathlib import Path
import argparse,json,re,mimetypes,functools,http.server,urllib.parse
DEFAULT_ROOT=Path('/workspace/work/publish/rhetis-component-rebuild-20261024')
WORK=Path('/workspace/work/rebuild-20261024')
NAMES=['nocturne','inflexion','diecut','afterglow','dockside','confluence']
EXPECTED={'nocturne':6,'inflexion':20,'diecut':19,'afterglow':9,'dockside':30,'confluence':4}
LABELS={'agenda':'목차','architecture':'아키텍처','balance':'균형 비교','bullet':'불릿 차트','callout':'콜아웃','card':'카드','chart-area':'영역 차트','chart-bar':'막대 차트','chart-donut':'도넛','chart-line':'선 차트','chart-scatter':'산점도·버블','chart-stack':'누적 막대','chart-waterfall':'워터폴','code':'코드','concentric':'포함 관계','cycle':'순환','decision-tree':'의사결정 나무','delta':'변화','flowchart':'순서도','funnel':'퍼널','gauge':'미터','headline':'제목','heatmap':'히트맵','hierarchy':'계층도','hub':'허브','image-frame':'이미지 프레임','journey':'여정','legend':'범례','list':'목록','logo-group':'로고 모음','matrix':'2×2 매트릭스','matrix-nine':'9칸 매트릭스','metric':'지표','mindmap':'마인드맵','network':'네트워크','person':'인물','pill':'필','positioning':'포지셔닝','pricing':'가격표','prose':'본문','pyramid':'피라미드','quote':'인용','radar':'레이더','roadmap':'로드맵','sankey':'생키','slope':'슬로프·덤벨','sparkline':'스파크라인','steps':'단계','swimlane':'스윔레인','table':'표','tag':'태그·강조','timeline':'타임라인','treemap':'트리맵','venn':'벤 다이어그램','versus':'양자 비교','waffle':'와플·픽토그램'}

def read_json(p,default=None):
 try:return json.loads(p.read_text())
 except (OSError,ValueError):return {} if default is None else default

def review_path(root,name):
 p=root/'reviews'/name
 return p if (p/'map.json').exists() else WORK/name/'review'

def collection_path(root,name):
 p=root/'collections'/name
 return p if (p/'elements').exists() else WORK/name/'collection'/name

def page_number(value):
 m=re.search(r'\d+',str(value));return m.group().zfill(2)if m else str(value)

def build_data(root):
 delivery=read_json(root/'delivery-validation.json');staged=bool(delivery)
 records={x.get('collection'):x for x in delivery.get('collections',[])if isinstance(x,dict)}
 leaf_names=set()
 for n in NAMES:leaf_names.update(p.name for p in (collection_path(root,n)/'elements').glob('*')if p.is_dir())
 if not leaf_names:leaf_names.update(LABELS)
 leaves=sorted(leaf_names);collections=[]
 for n in NAMES:
  rr=review_path(root,n);cc=collection_path(root,n);mp=read_json(rr/'map.json');instances=mp.get('instances',[]);origins={k:[]for k in leaves};gaps={};pagefiles={}
  # Delivery validation is authoritative when available; filenames are kept
  # verbatim, including Diecut's slide-NN naming and Nocturne's pages19..24.
  for item in records.get(n,{}).get('pngs',[]):
   f=item.get('file','')
   if f.startswith('compare-reassembled/')and f.endswith('.png'):pagefiles[page_number(Path(f).stem)]=Path(f).name
  for p in (rr/'compare-reassembled').glob('*.png'):pagefiles.setdefault(page_number(p.stem),p.name)
  if not pagefiles:
   for x in instances:
    if x.get('page')is not None:pagefiles.setdefault(page_number(x['page']),'slide_'+page_number(x['page'])+'.png')
  for x in instances:
   k=x.get('leaf');use=str(x.get('use',''));pg=page_number(x.get('page',''))
   if use=='unexpressible':gaps.setdefault(pg,[]).append(str(x.get('design')or x.get('reason')or '계약으로 표현할 수 없는 형상'))
   if k in origins and(use=='base'or use.startswith('variant')):
    variant=str(x.get('variant')or (use.split(':',1)[1]if ':'in use else'')).strip()
    fixture=Path(str(x.get('fixture',''))).stem
    row={'page':pg,'kind':'base'if use=='base'else'variant','variant':variant,'fixtures':[fixture]if fixture else[],'design':str(x.get('design',''))}
    previous=next((a for a in origins[k]if(a['page'],a['kind'],a['variant'])==(row['page'],row['kind'],row['variant'])),None)
    if previous is None:origins[k].append(row)
    elif fixture and fixture not in previous['fixtures']:previous['fixtures'].append(fixture)
  leafinfo={}
  for k in leaves:
   desc=cc/'elements'/k/'description.md'
   try:description=desc.read_text().strip()
   except OSError:description=''
   leafinfo[k]={'label':LABELS.get(k,k),'origins':origins[k],'fixtures':len(list((cc/'elements'/k/'fixtures').glob('*.html'))),'description':description,'hasComparison':bool(origins[k])or(rr/'sheets'/(k+'-replica.png')).exists()}
  pages=[{'number':pg,'file':f,'gaps':gaps.get(pg,[])}for pg,f in sorted(pagefiles.items(),key=lambda x:int(x[0])if x[0].isdigit()else x[0])]
  collections.append({'name':n,'pages':pages,'leaves':leafinfo,'pageCount':len(pages)or EXPECTED[n],'gapCount':sum(len(v)for v in gaps.values()),'fixtureCount':records.get(n,{}).get('fixtures')or sum(x['fixtures']for x in leafinfo.values()),'elementCount':records.get(n,{}).get('elements')or len(leaves)})
 freeze=read_json(root/'replica-freeze-validation.json')or read_json(WORK/'replica-freeze-validation.json')
 return {'collections':collections,'leaves':leaves,'delivery':{'staged':staged,'integrity':delivery.get('allZipIntegrity'),'elements':delivery.get('totalElements',len(leaves)*len(NAMES)),'pages':delivery.get('totalPages',sum(x['pageCount']for x in collections)),'zips':delivery.get('zips',[])},'freeze':{'files':freeze.get('files',191),'unchanged':freeze.get('unchanged')},'date':'2026-10-24'}

