def build(root):
 data=build_data(root);payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026');root.mkdir(parents=True,exist_ok=True);out=root/'preview.html';out.write_text(HTML.replace('__DATA__',payload));print(json.dumps({'file':str(out),'collections':len(data['collections']),'leavesPerCollection':len(data['leaves']),'pages':data['delivery']['pages'],'stagedValidation':data['delivery']['staged']},ensure_ascii=False));return data

def serve(root,port):
 class Handler(http.server.SimpleHTTPRequestHandler):
  def __init__(self,*args,**kwargs):super().__init__(*args,directory=str(root),**kwargs)
  def translate_path(self,path):
   actual=Path(super().translate_path(path))
   if actual.exists():return str(actual)
   pieces=Path(urllib.parse.unquote(urllib.parse.urlsplit(path).path).lstrip('/')).parts
   if '..'in pieces:return str(actual)
   if len(pieces)>2 and pieces[0]=='reviews'and pieces[1]in NAMES:return str(WORK/pieces[1]/'review'/Path(*pieces[2:]))
   if len(pieces)>2 and pieces[0]=='collections'and pieces[1]in NAMES:return str(WORK/pieces[1]/'collection'/pieces[1]/Path(*pieces[2:]))
   if len(pieces)==1 and pieces[0]in ['element-origins.md','replica-freeze-validation.json']:return str(WORK/pieces[0])
   return str(actual)
 print('Draft viewer: http://127.0.0.1:'+str(port)+'/preview.html',flush=True)
 http.server.ThreadingHTTPServer(('127.0.0.1',port),Handler).serve_forever()

if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--root',type=Path,default=DEFAULT_ROOT);p.add_argument('--serve',action='store_true',help='Serve a read-only draft with workspace artifact fallbacks');p.add_argument('--port',type=int,default=8768);a=p.parse_args();build(a.root)
 if a.serve:serve(a.root,a.port)
